  sl=p.slides[i]; pics=[(j,s) for j,s in enumerate(sl.shapes) if s.shape_type==13]
  for s in sl.shapes:
   if not s.has_text_frame or not re.search(r'Model\s*[:\t]',s.text,re.I):continue
